urlset:
{%- assign posts = site.posts | where_exp: 'p', 'p.sitemap != false' %}
{%- for post in posts %}

    {{ post.url | absolute_url | xml_escape }}
    {{ post.last_modified_at | default: post.date | date_to_xmlschema }}

{%- endfor %}

    {{ '/' | absolute_url }}
    {{ site.posts.first.date | date_to_xmlschema }}

{%- assign pages = site.html_pages | where_exp: 'p', 'p.sitemap != false' | where_exp: 'p', 'p.noindex != true' %}
{%- for p in pages %}
  {%- unless p.url == '/' or p.url == '/index.html' or p.url contains '/page/' or p.url contains '404' %}

    {{ p.url | replace: '/index.html', '/' | absolute_url | xml_escape }}
    {%- if p.last_modified_at %}
    {{ p.last_modified_at | date_to_xmlschema }}
    {%- endif %}

  {%- endunless %}
{%- endfor %}
